\label{ssat < sat}
    For every oriented graph $G$, we have
    \[\mathrm{ssat}_{\mathrel{\scalebox{0.75}[1]{$\scriptstyle\rightarrow$}}}(n,G) \leq \mathrm{sat}_{\mathrel{\scalebox{0.75}[1]{$\scriptstyle\rightarrow$}}}(n,G).\]

\label{thm:ssat}
    For a given oriented graph $G$, we have 
    \[  \mathrm{ssat}_{\mathrel{\scalebox{0.75}[1]{$\scriptstyle\rightarrow$}}}(n,G) = 
    \begin{cases}
    O(1) & \text{if $G$ has an isolated edge,} \\
    \Theta(n) &
    \begin{aligned}
        &\text{if $G$ has no isolated edge and has an edge} \\
        &\text{with a compatible neighborhood,}
    \end{aligned} \\
    \Theta(n \log n) & \text{otherwise.}
    \end{cases}
    \]

\label{thm:acyclic}
    For every acyclic oriented graph $G$, we have 
 \[  \mathrm{sat}_{\mathrel{\scalebox{0.75}[1]{$\scriptstyle\rightarrow$}}}(n,G) = 
    \begin{cases}
         O(1) & \text{if $G$ has an isolated edge,} \\
         \Theta(n) & \text{otherwise.} \\         
    \end{cases}
    \]

\label{thm:orders}
    There are at least four distinct orders of magnitude for the saturation functions of oriented graphs, namely
    \[O(1),\Theta(n), \Theta(n\sqrt{\log n}), \text{ and }  \Theta(n\log n).\]

\label{ssat_n}
    Let $G$ be an oriented graph that contains no isolated edges, and there exists an edge $\overrightarrow{uv} \in E$ with a compatible neighborhood. Then
    \[\mathrm{ssat}_{\mathrel{\scalebox{0.75}[1]{$\scriptstyle\rightarrow$}}}(n,G) = \Theta(n).\]

\label{ssat_nlogn}
    Let $G$ be an oriented graph such that for each edge $\overrightarrow{uv} \in E$ there exists $w \in N_G(u) \cap N_G(v)$, such that either $\{\overrightarrow{uw}, \overrightarrow{wv}\} \subset E$ or $\{\overrightarrow{vw},\overrightarrow{wu}\} \subset E$. Then
    \[\mathrm{ssat}_{\mathrel{\scalebox{0.75}[1]{$\scriptstyle\rightarrow$}}}(n,G) = \Theta(n \log n).\]

\label{acyc_linear}
    For every acyclic oriented graph $G$ without isolated edges, we have 
    \[\mathrm{sat}_{\mathrel{\scalebox{0.75}[1]{$\scriptstyle\rightarrow$}}}(n,G) = \Theta(n).\]

\label{sat_nlogn}
    Let $G$ be an oriented graph with edge set $E$ such that for each edge $\overrightarrow{uv} \in E$ there exists $w \in N_G(u) \cap N_G(v)$, such that either $\{\overrightarrow{uw}, \overrightarrow{wv}\} \subset E$ or $\{\overrightarrow{vw},\overrightarrow{wu}\} \subset E$. If in addition there exists $\overrightarrow{xy} \in E$ such that both $N_G(x) \setminus \{y\}$ and $N_G(y) \setminus \{x\}$ form independent sets, then
    \[\mathrm{sat}_{\mathrel{\scalebox{0.75}[1]{$\scriptstyle\rightarrow$}}}(n,G) = \Theta(n \log n).\]

\label{bip nlogn upper}
    Let $G$ be an oriented graph such that there exists an edge $\overrightarrow{uv} \in E$ for which $N_G(u) \cap N_G(v) \neq \emptyset$, and the graph obtained from $G$ by removing the edge $\overrightarrow{uv}$ is bipartite. Then
    \[\mathrm{sat}_{\mathrel{\scalebox{0.75}[1]{$\scriptstyle\rightarrow$}}}(n,G) = O(n \log n).\]
